#! /usr/bin/env dcli
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;
import 'package:dcli/dcli.dart';
const draws=10000;
const upperIndex=9500;
final mask=(BigInt.one<<64)-BigInt.one;
const raw='/home/bsutton/git/.codex.workspaces/revault-issue-310-zip-read-performance/docs/evidence/secure-arena-reclamation-2026-10-12/raw/hot-reuse-methodology-review';
void require(bool ok,String why){if(!ok)throw StateError(why);}
double finitePositive(Object? value,String label){require(value is num,'$label must be numeric');final v=(value as num).toDouble();require(v.isFinite&&v>0,'$label must be finite and positive');return v;}
BigInt seedFor(int size,String metric){final code=metric=='inner'?BigInt.parse('494e4e4552',radix:16):BigInt.parse('50524f43455353',radix:16);return (BigInt.from(10000)^BigInt.from(size)^code)&mask;}
class SplitMix64{BigInt state;SplitMix64(this.state);BigInt next(){state=(state+BigInt.parse('9e3779b97f4a7c15',radix:16))&mask;var z=state;z=((z^(z>>30))*BigInt.parse('bf58476d1ce4e5b9',radix:16))&mask;z=((z^(z>>27))*BigInt.parse('94d049bb133111eb',radix:16))&mask;return z^(z>>31);}}
List<Map<String,dynamic>> schedule(){final out=<Map<String,dynamic>>[];for(var round=0;round<14;round++){for(final size in [64,65536]){final order=round.isEven?['old','new']:['new','old'];for(final variant in order){out.add({'round':round,'size_bytes':size,'iterations':size==64?100000:10000,'variant':variant,'preparation_round':round<2});}}}return out;}
List<double> bootstrap(List<double> logRatios,int size,String metric){require(logRatios.length==6,'requires exactly six paired blocks');final rng=SplitMix64(seedFor(size,metric));final values=<double>[];for(var draw=0;draw<draws;draw++){var sum=0.0;for(var i=0;i<6;i++){final j=(rng.next()%BigInt.from(6)).toInt();sum+=logRatios[j];}values.add((sum/6).exp());}values.sort();return values;}
Future<void> main(List<String> args)async{final input=args.isEmpty?'$raw/samples.jsonl':args.single;final f=File(input);require(f.existsSync(),'missing admitted sample file: $input');final rows=f.readAsLinesSync().where((x)=>x.trim().isNotEmpty).map((x)=>jsonDecode(x) as Map<String,dynamic>).toList();final expected=schedule();require(rows.length==56,'expected exactly 56 admitted process records');for(var i=0;i<56;i++){final row=rows[i],want=expected[i];for(final key in ['round','size_bytes','iterations','variant','preparation_round','kind']){require(row[key]==(key=='kind'?'hot_reuse':want[key]),'record $i mismatch for $key');}require(row['exit_code']==0&&row['byte_verification_ok']==true&&row['weak_policy']==false,'record $i failed execution/security admission');require(row['memlock_soft_bytes']==8388608&&row['memlock_hard_bytes']==8388608,'record $i memlock changed');require(row['baseline_VmLck_bytes']==0,'record $i baseline VmLck must be zero');final vm=<int>[];for(final key in ['prewarm_live_VmLck_bytes','before_inner_VmLck_bytes','after_inner_VmLck_bytes']){final v=row[key];require(v is num&&v>0&&v<=8388608,'record $i invalid $key');vm.add((v as num).toInt());}require(vm.toSet().length==1,'record $i VmLck values are not equal and positive');require(row['execution_mode']=='hot-reuse-fixed-56-v1','record $i execution-mode label mismatch');finitePositive(row['inner_elapsed_ns'],'record $i inner_elapsed_ns');finitePositive(row['whole_process_elapsed_ns'],'record $i whole_process_elapsed_ns');}
final reports=<Map<String,Object>>[];for(final size in [64,65536]){for(final metric in ['inner','process']){final logs=<double>[];for(var block=0;block<6;block++){final rounds=[block*2+2,block*2+3];final ratios=<double>[];for(final round in rounds){final pair=rows.where((r)=>r['round']==round&&r['size_bytes']==size).toList();require(pair.length==2,'missing/duplicate round pair');final old=pair.singleWhere((r)=>r['variant']=='old');final newer=pair.singleWhere((r)=>r['variant']=='new');final oldTime=metric=='inner'?finitePositive(old['inner_elapsed_ns'],'old inner')/(old['iterations'] as int):finitePositive(old['whole_process_elapsed_ns'],'old process');final newTime=metric=='inner'?finitePositive(newer['inner_elapsed_ns'],'new inner')/(newer['iterations'] as int):finitePositive(newer['whole_process_elapsed_ns'],'new process');ratios.add(newTime/oldTime);}logs.add(ratios.map((x)=>x.log()).reduce((a,b)=>a+b)/ratios.length);}final drawsSorted=bootstrap(logs,size,metric);reports.add({'size_bytes':size,'metric':metric,'block_log_ratios':logs,'seed':seedFor(size,metric).toRadixString(16).padLeft(16,'0'),'bootstrap_draws':draws,'upper95_percentile':0.95,'upper95_index':upperIndex,'upper95_ratio':drawsSorted[upperIndex],'gate_pass':drawsSorted[upperIndex]<=1.05});}}
final result={'sample_count':rows.length,'preparation_rounds_excluded':[0,1],'measured_rounds':[2,13],'adjacent_blocks':6,'bootstrap':'SplitMix64 mod 6, percentile index 9500','endpoints':reports,'all_four_noninferiority_gates_pass':reports.every((x)=>x['gate_pass']==true)};File('$raw/analysis.json').writeAsStringSync('${const JsonEncoder.withIndent('  ').convert(result)}\n',flush:true);print(green(const JsonEncoder.withIndent('  ').convert(result)));}
extension on double{double exp()=>math.exp(this);double log()=>math.log(this);}
